declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); c public.company_cases; again public.company_cases; personal uuid; snap jsonb; count_rows integer;
begin
 insert into auth.users(id,aud,role,email) values(a,'authenticated','authenticated','action-owner@example.invalid'),(b,'authenticated','authenticated','action-reviewer@example.invalid'),(outsider,'authenticated','authenticated','action-outsider@example.invalid');
