 snap:='{"title":"Synthetic safety alert","link":"https://regulator.example/alert","published":"2026-10-30T00:00:00Z","companyContext":{"companyId":"synthetic","companyName":"Synthetic company","markets":["EU"],"products":[],"reason":"Confirmed substance match","portfolioRevision":1}}';
 insert into public.team_items(team_id,update_id,snapshot) values(t,'synthetic-team-source',snap);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email','action-owner@example.invalid','role','authenticated')::text,true);
 execute 'set local role authenticated';
 c:=public.open_company_case('synthetic-personal-source',snap,null);personal:=c.id;
 again:=public.open_company_case('synthetic-personal-source',snap,null);
 if c.id<>again.id then raise exception 'Duplicate case created';end if;
