 begin perform public.advance_company_case(c.id,c.version,'assign','{"type":"Signal evaluation","owner":"A name","due":"2026-11-01","instruction":"Review"}');raise exception 'Expected email rejection';exception when others then if sqlerrm not like 'Use an email%' then raise;end if;end;
 begin update public.company_cases set stage='closed' where id=c.id;raise exception 'Expected direct write rejection';exception when insufficient_privilege then null;end;
 c:=public.advance_company_case(c.id,c.version,'assign','{"type":"Signal evaluation","owner":"action-owner@example.invalid","due":"2026-11-01","instruction":"Review product evidence"}');
 begin perform public.advance_company_case(c.id,c.version,'complete','{"changed":"Reviewed"}');raise exception 'Expected evidence rejection';exception when others then if sqlerrm not like 'Attach supporting%' then raise;end if;end;
 c:=public.advance_company_case(c.id,c.version,'complete','{"changed":"Evaluation completed","evidence":[{"label":"Report","url":"https://documents.example/report"}]}');
 c:=public.advance_company_case(c.id,c.version,'approve','{"reason":"Evidence reviewed"}');
 if c.stage<>'closed' or c.approval->>'selfReview'<>'true' then raise exception 'Personal self-review failed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'email','action-reviewer@example.invalid','role','authenticated')::text,true);
 select count(*) into count_rows from public.company_cases where id=personal;if count_rows<>0 then raise exception 'Personal case leaked';end if;
 begin perform public.advance_company_case(personal,5,'reopen','{"reason":"Unauthorized"}');raise exception 'Expected isolation';exception when others then if sqlerrm not like 'Case unavailable%' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email','action-owner@example.invalid','role','authenticated')::text,true);
 c:=public.open_company_case('synthetic-team-source',null,t);
 c:=public.advance_company_case(c.id,c.version,'decide','{"decision":"relevant","reason":"Team product match"}');
 begin perform public.advance_company_case(c.id,c.version,'assign','{"type":"Signal evaluation","owner":"nobody@example.invalid","due":"2026-11-01","instruction":"Review"}');raise exception 'Expected team owner membership rejection';exception when others then if sqlerrm not like 'Action owner must%' then raise;end if;end;
 c:=public.advance_company_case(c.id,c.version,'assign','{"type":"Signal evaluation","owner":"action-owner@example.invalid","due":"2026-11-01","instruction":"Review evidence"}');
 begin perform public.advance_company_case(c.id,c.version,'complete','{"changed":"Evaluation done","reviewer":"action-owner@example.invalid","evidence":[{"label":"Report","url":"https://documents.example/report"}]}');raise exception 'Expected self approval rejection';exception when others then if sqlerrm not like 'Choose a different%' then raise;end if;end;
 c:=public.advance_company_case(c.id,c.version,'complete','{"changed":"Evaluation done","reviewer":"action-reviewer@example.invalid","evidence":[{"label":"Report","url":"https://documents.example/report"}]}');
 begin perform public.advance_company_case(c.id,c.version,'approve','{"reason":"Self approval attempt"}');raise exception 'Expected reviewer rejection';exception when others then if sqlerrm not like 'Only the designated%' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'email','action-outsider@example.invalid','role','authenticated')::text,true);
 select count(*) into count_rows from public.company_cases;if count_rows<>0 then raise exception 'Company work leaked to nonmember';end if;
