 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'email','action-reviewer@example.invalid','role','authenticated')::text,true);
 c:=public.advance_company_case(c.id,c.version,'return','{"reason":"Additional analysis required"}');if c.stage<>'action' or c.completion is not null then raise exception 'Rework state failed';end if;
 begin perform public.advance_company_case(c.id,c.version,'complete','{"changed":"Reviewer cannot submit owner work","reviewer":"action-owner@example.invalid","evidence":[{"label":"Report","url":"https://documents.example/report"}]}');raise exception 'Expected owner rejection';exception when others then if sqlerrm not like 'Only the assigned%' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email','action-owner@example.invalid','role','authenticated')::text,true);
 c:=public.advance_company_case(c.id,c.version,'complete','{"changed":"Rework completed","reviewer":"action-reviewer@example.invalid","evidence":[{"label":"Revised report","url":"https://documents.example/revised"}]}');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'email','action-reviewer@example.invalid','role','authenticated')::text,true);
 c:=public.advance_company_case(c.id,c.version,'approve','{"reason":"Revised evidence verified"}');
 if c.stage<>'closed' or c.approval->>'selfReview'<>'false' or jsonb_array_length(c.history)<>c.version then raise exception 'Independent closure history failed';end if;
 c:=public.advance_company_case(c.id,c.version,'reopen','{"reason":"New safety evidence"}');if c.stage<>'assessment' or c.approval is not null then raise exception 'Reopen failed';end if;
 execute 'reset role';
end $$;
rollback;
select 'PASS: private/team isolation, duplicate prevention, state gates, optimistic concurrency, email-only owner, evidence requirements, independent reviewer, rework, reopen, immutable writes; all fixtures rolled back' as result;
